property.value:
let $value := function($arg) {
      if ($arg[self::StringLiteral]) then string($arg/@ConstValue)
      else if ($arg[self::VariableAccess]) then
        (let $declared := root($arg)//FieldDeclaration[ModifierList/@ExplicitModifiers = 'final'][ModifierList/@ExplicitModifiers = 'static']
                            /VariableDeclarator[@Name = $arg/@Name][*[last()][self::StringLiteral]]
         return if (count($declared) = 1) then string($declared/*[last()]/@ConstValue) else ())
      else ()
    },
    $bad := function($arg, $legacy) {
      let $raw := $value($arg),
          $p := replace(replace($raw, "''", ''), "'[^']*'", ''),
          $marker := matches($p, '[aB]')
      return exists($raw) and ((matches($p, '[HhKk]{1,2}[:.]M{1,2}([^M]|$)')
                and not($legacy and count(analyze-string($p, 'M+')/*:match) >= 2))
        or matches($p, '^[^HhKk]*([dyM]+[-./]m+|m+[-./][dyM]+)')
        or matches($p, '(^|[^y])(yyy|y{5,})([^y]|$)')
        or matches($p, 'k')
        or (matches($p, 'K') and not($marker))
        or (matches($p, 'h') and not($marker) and not($legacy and matches($p, 'hh')))
        or (matches($p, 'h') and matches($p, 'H') and not($marker))
        or matches($p, '[HhKk]{1,2}[:.]s'))
    }
return (
  //ConstructorCall[ClassType[@SimpleName = 'SimpleDateFormat']]/ArgumentList/*[1]
    [$bad(., true())],
  //MethodCall[@MethodName = ('applyPattern', 'applyLocalizedPattern')][*[1][pmd-java:typeIs('java.text.SimpleDateFormat')]]
    /ArgumentList/*[1][$bad(., true())],
  //MethodCall[@MethodName = 'ofPattern'][*[1][self::TypeExpression/ClassType/@SimpleName = 'DateTimeFormatter' or self::AmbiguousName/@Name = 'DateTimeFormatter']]
    /ArgumentList/*[1][$bad(., false())],
  //MethodCall[@MethodName = 'appendPattern'][*[1][pmd-java:typeIs('java.time.format.DateTimeFormatterBuilder')]]
    /ArgumentList/*[1][$bad(., false())]
)
